#include "closed_transpose_arithmetic.hpp"
bool pole_sqrt(const F& a,int degree,F& root){if(a==F(0)){root=F(0);return true;}mpz_class q;mpz_pow_ui(q.get_mpz_t(),prime.get_mpz_t(),unsigned(degree));if(a.power(mpz_class((q-1)/2))!=F(1))return false;if(q%4==3){root=a.power(mpz_class((q+1)/4));return root*root==a;}mpz_class odd=q-1;int s=0;while(mpz_even_p(odd.get_mpz_t())){odd>>=1;++s;}F nonresidue;bool found=false;for(int shift=0;shift<1024;++shift){F z(CFPoly{Z(shift),Z(1)});if(z!=F(0)&&z.power(mpz_class((q-1)/2))==F(-1)){nonresidue=z;found=true;break;}}require(found,"pole Tonelli nonresidue cap");F c=nonresidue.power(odd),t=a.power(odd),x=a.power(mpz_class((odd+1)/2));int m=s;while(t!=F(1)){F v=t*t;int i=1;while(i<m&&v!=F(1)){v=v*v;++i;}require(i<m,"pole Tonelli order");F b=c.power(mpz_class(1)<<(m-i-1));x=x*b;t=t*b*b;c=b*b;m=i;}root=x;require(root*root==a,"pole field square root replay");return true;}
int main(int argc,char** argv){try{
    require(argc==4,"usage: pole_cases study global bridge");std::string root=argv[1];initialize_cover(read_json(root+"/inputs/p192-d7-prym.json"));Level2Input input;auto global=read_json(argv[2]),model=read_json(root+"/evidence/p192-d7-kernel3-plane-quartic.json");EBPoly f;for(auto& row:model.at("terms").arr){auto e=row.at("exponents");f.add({e.arr[0].integer(),e.arr[1].integer()},Z(mpz_class(row.at("coefficient").scalar)));}MMap map(global,f);CFPoly radical=map.den.exact(cf_gcd(map.den,cf_derivative(map.den))).monic(),remaining=radical,x{Z(0),Z(1)},power=x;std::vector<CFPoly> factors;for(int d=1;d<=3&&remaining.degree()>0;++d){power=powmod(power,prime,remaining);auto block=cf_gcd(remaining,power-x);if(block.degree()>0){ct_equal(block,d,factors);remaining=remaining.exact(block).monic();if(remaining.degree()>0)power=power%remaining;}}CFPoly replay=remaining;for(auto& q:factors){ct_irreducible(q);replay=replay*q;}require(replay==radical,"pole low-degree factor replay");if(remaining.degree()>0){auto a=x;for(int d=1;d<=3;++d){a=powmod(a,prime,remaining);require(cf_gcd(remaining,a-x).degree()==0,"no remaining degree1/2/3 factors");}}
    std::vector<MForward> images;std::vector<int> factor_indices;std::vector<bool> squares;auto saved=modulus;for(size_t i=0;i<factors.size();++i){modulus=factors[i];F z(CFPoly{Z(0),Z(1)}),rhs=ct_eval(map.h,z),y;bool square=pole_sqrt(rhs,factors[i].degree(),y);squares.push_back(square);if(!square){modulus=saved;continue;}std::vector<CFPoly> vs{y.a};if(y!=F(0))vs.push_back((-y).a);modulus=saved;for(auto v:vs){G source{tr_embed(factors[i]),tr_embed(v)};source.check();auto image=map.forward(source);require(image.shift>=0&&cf_gcd(image.e,map.den).degree()==0,"actual pole automatically moved");images.push_back(image);factor_indices.push_back(int(i));std::cerr<<"actual pole factor "<<i<<" degree="<<factors[i].degree()<<" move="<<image.shift<<" passed\n";}}
    std::cout<<"{\"scope\":\"P192-actual-low-degree-denominator-pole-fixtures\",\"standing\":\"producer-unverified\",\"denominator\":";cf_emit_poly(map.den);std::cout<<",\"remaining\":";cf_emit_poly(remaining);std::cout<<",\"factors\":[";for(size_t i=0;i<factors.size();++i){if(i)std::cout<<',';std::cout<<"{\"factor\":";cf_emit_poly(factors[i]);std::cout<<",\"h_square\":"<<(squares[i]?"true":"false")<<'}';}std::cout<<"],\"automatic_moving_cases\":"<<images.size()<<",\"images\":[";for(size_t i=0;i<images.size();++i){if(i)std::cout<<',';std::cout<<"{\"factor_index\":"<<factor_indices[i]<<",\"image\":";cm_emit_forward(images[i]);std::cout<<'}';}std::cout<<"],\"all_reduced_exceptional_supports_classified\":false}\n";
}catch(const std::exception& e){std::cerr<<"REJECT "<<e.what()<<'\n';return 1;}}
